using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace RhythmWare.Education
{
    [Serializable]
    public class CyberQuestion
    {
        public string id,category,questionText,explanation,relatedThreat,objectiveId,lessonTitle,lessonText;
        public string[] options,optionFeedback;
        public int correctIndex;
    }
    public static class CyberQuestionBank
    {
        public const int ContentVersion=2;
        static List<CyberQuestion> questions;
        public static readonly string[] CoreThreats={"Spyware","Adware","Trojan","Ransomware","DDoS"};
        public static string Name(string threat)=>threat=="Trojan"?"Troyanos":threat=="DDoS"?"Ataques DDoS":threat;
        public static string BriefingSummary(string threat)
        {
            switch(threat)
            {
                case "Spyware":return "Recoge datos sin autorización; puede no dar señales visibles. Revisa permisos, fuentes y protección. Ante una fuga: aísla y avisa a SOC/TI. Tras limpiar: cambia credenciales expuestas desde un equipo confiable y revoca sesiones desconocidas.";
                case "Adware":return "Anuncios y redirecciones no deseados pueden generar ingresos al atacante. Revisa el instalador y rechaza extras premarcados. Usa fuentes oficiales. Un bloqueador de anuncios no elimina el software instalado; publicidad y espionaje pueden coexistir.";
                case "Trojan":return "Una utilidad puede funcionar y ocultar una carga maliciosa. Comprueba la fuente antes de ejecutar; un logo o HTTPS no garantizan legitimidad. No conectes USB desconocidos: entrégalos a TI. Ante acceso oculto: aísla y coordina la recuperación.";
                case "Ransomware":return "Cifra archivos y puede robar datos para extorsionar. Primero aísla y avisa a respuesta a incidentes. 3-2-1: tres copias, dos medios, una fuera del sitio; añade protección offline/inmutable y prueba restauraciones. Recupera en sistemas limpios. Pagar no garantiza acceso.";
                default:return "DDoS es un ataque distribuido contra la disponibilidad, no una familia de malware. La lentitud sola no lo confirma: analiza tráfico y recursos. Coordina filtrado upstream con ISP/CDN o proveedor anti-DDoS; un firewall local no basta si el enlace ya está saturado.";
            }
        }
        public static List<CyberQuestion> GetAllQuestions(){if(questions==null)Build();return questions;}
        public static CyberQuestion GetRandomQuestion(){var q=GetAllQuestions();return q[UnityEngine.Random.Range(0,q.Count)];}
        public static CyberQuestion GetRandomQuestionForThreat(string threat)
        {
            string key=Normalize(threat);var q=GetAllQuestions().Where(x=>x.relatedThreat==key).ToList();
            return q.Count>0?q[UnityEngine.Random.Range(0,q.Count)]:GetRandomQuestion();
        }
        public static CyberQuestion GetRandomQuestionByCategory(string category)
        {var q=GetAllQuestions().Where(x=>x.category.Equals(category,StringComparison.OrdinalIgnoreCase)).ToList();return q.Count>0?q[UnityEngine.Random.Range(0,q.Count)]:GetRandomQuestion();}
        public static string Normalize(string value)
        {
            value=value??"";foreach(var t in CoreThreats)if(value.IndexOf(t,StringComparison.OrdinalIgnoreCase)>=0)return t;
            if(value.IndexOf("Troya",StringComparison.OrdinalIgnoreCase)>=0)return "Trojan";
            if(value.IndexOf("Keylog",StringComparison.OrdinalIgnoreCase)>=0)return "Spyware";return "";
        }
        static void Add(string id,string threat,string objective,string title,string lesson,string scenario,string answer,string wrong1,string wrong2,string explanation,string reason1,string reason2)
        {
            int position=questions.Count%3;var options=new string[3];var feedback=new string[3];
            options[position]=answer;feedback[position]=explanation;options[(position+1)%3]=wrong1;options[(position+2)%3]=wrong2;
            feedback[(position+1)%3]=reason1+" "+explanation;feedback[(position+2)%3]=reason2+" "+explanation;
            questions.Add(new CyberQuestion{id="v2-"+id,relatedThreat=threat,category=Name(threat),objectiveId=objective,lessonTitle=title,lessonText=lesson,questionText=scenario,options=options,correctIndex=position,explanation=explanation,optionFeedback=feedback});
        }
        static void Build()
        {
            questions=new List<CyberQuestion>();
            Add("spy-1","Spyware","spy-identify","Espionaje sin señales visibles","Spyware recopila y envía datos sin autorización. Un keylogger puede registrar teclas; no siempre notarás lentitud o avisos.","Una extensión envía historial y capturas a un tercero sin avisar. ¿Qué comportamiento predomina?","Espionaje y fuga de datos: Spyware.","Publicidad invasiva: Adware.","Saturación distribuida: DDoS.","La recolección no autorizada y silenciosa caracteriza al spyware.","No se describen anuncios ni redirecciones.","No se describe saturación de un servicio.");
            Add("spy-2","Spyware","spy-prevent","Permisos con sentido","Descarga desde fuentes confiables, revisa permisos y mantén protección actualizada. Estas medidas reducen el riesgo; no garantizan ausencia de malware.","Una linterna solicita acceso permanente al micrófono y tus contactos. ¿Qué decisión reduce el riesgo?","Rechazar permisos innecesarios y buscar una aplicación confiable.","Aceptar los permisos si la aplicación funciona bien.","Aceptar y confiar solo en un análisis posterior.","Los permisos deben corresponder a la función de la aplicación y revisarse antes de concederlos.","Que una aplicación funcione no justifica permisos excesivos.","Un análisis posterior no deshace datos ya filtrados.");
            Add("spy-3","Spyware","spy-contain","Contener una fuga","Ante tráfico saliente sospechoso, aísla el equipo afectado y avisa a SOC/TI. Sigue el procedimiento de incidentes y conserva evidencias.","El SOC confirma envío no autorizado de credenciales desde un equipo. ¿Qué prioriza?","Aislar ese equipo de la red y notificar al equipo de respuesta.","Cambiar la contraseña desde ese mismo equipo y seguir trabajando.","Esperar al análisis nocturno antes de interrumpir la conexión.","El aislamiento ayuda a frenar la exfiltración; la investigación y limpieza se coordinan con respuesta a incidentes.","El equipo aún comprometido puede capturar la nueva contraseña.","La fuga puede continuar mientras se espera.");
            Add("spy-4","Spyware","spy-recover","Recuperar tus cuentas","Después de limpiar o reinstalar el equipo, cambia credenciales expuestas desde un dispositivo confiable, cierra sesiones desconocidas y revisa MFA y accesos.","Ya eliminaron spyware que estuvo activo varios días. ¿Qué falta hacer?","Renovar credenciales expuestas y revocar sesiones desde un equipo confiable.","Conservar las contraseñas porque el malware ya se eliminó.","Cambiar solamente el fondo de pantalla y reiniciar.","Eliminar el programa no recupera secretos ni invalida sesiones que el atacante ya obtuvo.","Las credenciales robadas pueden seguir siendo válidas.","La apariencia del escritorio no protege las cuentas.");
            Add("ad-1","Adware","ad-identify","Publicidad que no elegiste","Adware muestra anuncios o redirige búsquedas sin consentimiento para generar ingresos. Se distingue del objetivo de espionaje, aunque pueden coexistir.","Un navegador cambia de buscador y abre anuncios sin permiso. ¿Qué describe mejor el caso?","Adware o secuestro publicitario del navegador.","Un DDoS contra el servidor visitado.","Cifrado de archivos por ransomware.","El objetivo visible es monetizar publicidad o redirecciones no solicitadas.","Un DDoS afecta disponibilidad; no explica esos cambios locales.","No hay archivos cifrados ni extorsión en este caso.");
            Add("ad-2","Adware","ad-install","Lee el instalador","Programas extra pueden venir incluidos en un instalador. Revisa cada paso, desmarca complementos desconocidos y cancela si no puedes rechazarlos.","Un instalador trae seleccionadas dos barras de búsqueda adicionales. ¿Qué haces?","Rechazar los extras desconocidos o cancelar la instalación.","Continuar porque vienen marcados de fábrica.","Instalar todo y borrar solo los iconos después.","No concedas consentimiento a software que no pediste; quitar un icono no desinstala el programa.","Una casilla premarcada no prueba que el complemento sea necesario o confiable.","El software puede seguir activo aunque borres su acceso directo.");
            Add("ad-3","Adware","ad-source","Fuentes y mantenimiento","Usa canales oficiales y evita paquetes modificados. Revisa extensiones y programas instalados; un bloqueador de anuncios no sustituye la limpieza del sistema.","Un sitio ofrece una versión modificada de una app con un gestor obligatorio. ¿Qué opción es más segura?","Obtener la app desde su canal oficial y revisar los componentes.","Usar el paquete modificado porque tiene más funciones.","Instalarlo y confiar solo en el bloqueador del navegador.","La fuente y el contenido del instalador importan; el bloqueador no elimina software instalado.","Más funciones anunciadas no acreditan seguridad.","El adware puede afectar más que las páginas bloqueadas.");
            Add("ad-4","Adware","ad-compare","Dos objetivos distintos","Spyware recoge datos de forma oculta. Adware prioriza publicidad o redirecciones visibles. Un mismo programa puede tener ambos comportamientos.","¿Qué dato diferencia mejor publicidad invasiva de espionaje en dos incidentes?","Anuncios/redirecciones frente a recolección silenciosa no autorizada.","Si el ordenador es portátil o de escritorio.","Si ambos programas tienen un icono atractivo.","Se clasifica por el comportamiento y el objetivo observado, no por la apariencia del equipo o programa.","El tipo de equipo no define la amenaza.","Un icono no revela lo que hace el programa.");
            Add("trojan-1","Trojan","trojan-disguise","Una utilidad puede ocultar daño","Un troyano aparenta ser útil o legítimo para que lo ejecutes. Puede funcionar como promete y, al mismo tiempo, instalar una carga maliciosa.","Una utilidad funciona, pero instala acceso remoto oculto. ¿Qué explica el engaño?","Un troyano disfrazado de programa útil.","Una prueba de que la utilidad es segura porque funciona.","Un ataque DDoS que modifica el instalador a distancia.","La funcionalidad aparente no descarta una carga oculta o acceso no autorizado.","El comportamiento útil y el malicioso pueden coexistir.","No se describe una denegación de servicio distribuida.");
            Add("trojan-2","Trojan","trojan-vector","El engaño abre la puerta","Un archivo, adjunto o instalador engañoso puede inducir a ejecutar código. El nombre, reseñas o un candado HTTPS no garantizan legitimidad.","Te ofrecen un actualizador desde un mensaje no solicitado. ¿Cómo procedes?","Comprobar la actualización en el canal oficial sin ejecutar el adjunto.","Ejecutarlo si el mensaje usa el logo correcto.","Ejecutarlo si la página tiene HTTPS.","Verifica por un canal independiente y confiable antes de ejecutar software o conceder permisos.","Un logo se puede copiar.","HTTPS protege la conexión, no acredita al programa descargado.");
            Add("trojan-3","Trojan","trojan-usb","La curiosidad también es un vector","Un USB desconocido puede contener malware o hardware malicioso. Entrégalo a TI/seguridad sin conectarlo. Su etiqueta no identifica la familia concreta.","Aparece un USB con una etiqueta llamativa en tu oficina. ¿Qué haces?","Entregarlo a TI/seguridad sin conectarlo.","Abrirlo en tu equipo para identificar al propietario.","Conectarlo en un equipo personal para no afectar a la empresa.","No conectes dispositivos de procedencia desconocida; el análisis debe hacerlo personal preparado.","Buscar al dueño no justifica exponer tu equipo.","Un equipo personal también puede quedar comprometido.");
            Add("trojan-4","Trojan","trojan-response","Revoca la confianza indebida","Si ejecutaste una herramienta sospechosa con acceso oculto, detén su uso, aísla el equipo y avisa a TI. Quitar la app no prueba que se eliminó toda la carga.","Descubren acceso remoto no autorizado después de instalar una app. ¿Qué es adecuado?","Aislar el equipo y coordinar investigación y recuperación con TI.","Desinstalar la app y asumir que el incidente terminó.","Pedir al supuesto proveedor que siga controlando el equipo.","Se debe evaluar el alcance del acceso y recuperar el sistema de forma controlada.","Una carga adicional o credenciales expuestas pueden permanecer.","El acceso remoto sospechoso no debe seguir autorizado.");
            Add("ransom-1","Ransomware","ransom-identify","Cifrado y extorsión","El ransomware puede cifrar datos y exigir pago; también puede robar información y amenazar con publicarla. La prioridad no es el pago.","No puedes abrir archivos y aparece una exigencia de dinero. ¿Qué sospechas?","Un incidente de ransomware que requiere respuesta coordinada.","Adware porque aparece un mensaje en pantalla.","Una garantía de que pagar resolverá el incidente.","Cifrado y extorsión son señales de ransomware; pagar no garantiza recuperación ni elimina el compromiso.","No toda ventana visible es publicidad.","No hay garantía de que el atacante cumpla o de que termine el incidente.");
            Add("ransom-2","Ransomware","ransom-contain","Primero contener","Ante cifrado activo, aísla sistemas afectados de la red y avisa a respuesta a incidentes. La limpieza y restauración vienen después y deben evitar reinfección.","Un servidor empieza a cifrar carpetas compartidas. ¿Qué priorizas?","Aislar el sistema afectado y activar el procedimiento de respuesta.","Conectar el disco de backup para restaurar mientras sigue infectado.","Esperar a que termine para no interrumpir procesos.","Contener el incidente ayuda a limitar la propagación y protege la recuperación posterior.","El backup conectado podría quedar expuesto o la restauración reinfectarse.","Esperar permite que el daño continúe.");
            Add("ransom-3","Ransomware","ransom-backup","Copias 3-2-1 verificadas","La regla 3-2-1: tres copias en total, dos tipos de medio y una copia fuera del sitio. Añade copias offline o inmutables y prueba la restauración; no es una garantía absoluta.","¿Qué estrategia ofrece mayor resiliencia frente a pérdida y cifrado?","Tres copias, dos medios y una fuera del sitio, protegidas y con restauración probada.","Tres carpetas dentro del mismo disco siempre conectado.","Una sincronización sin versiones como única copia.","Fuera del sitio y offline son propiedades distintas. Una copia íntegra y una recuperación comprobada son esenciales.","Un único disco o incidente puede afectar las tres carpetas.","La sincronización puede replicar cambios maliciosos o borrados.");
            Add("ransom-4","Ransomware","ransom-recover","Recuperar sin depender del atacante","Recupera desde copias limpias y verificadas en sistemas confiables. Pagar no garantiza acceso ni borrado de datos robados. Sin copias o descifrador confiable quizá no sea posible recuperar todo.","Tras contener ransomware, ¿qué permite una recuperación controlada?","Restaurar copias verificadas en sistemas limpios y revisar el alcance del incidente.","Pagar y dar por seguro que todos los datos volverán.","Restaurar sobre el mismo sistema sin revisar la infección.","La recuperación requiere integridad y limpieza; ningún procedimiento debe prometer un resultado del 100%.","El pago no obliga al atacante a devolver o borrar datos.","Restaurar sin sanear puede repetir el daño.");
            Add("ddos-1","DDoS","ddos-identify","Un ataque, no una especie de malware","DDoS es denegación de servicio desde múltiples orígenes: satura recursos e impide acceso legítimo. Una botnet puede generarlo; no todo DDoS necesita dispositivos infectados.","Miles de orígenes saturan un portal e impiden atender usuarios. ¿Qué describe el caso?","Denegación de servicio distribuida: DDoS.","Cifrado local de archivos por ransomware.","Publicidad incluida en el navegador.","El objetivo primario descrito es afectar la disponibilidad del servicio mediante saturación distribuida.","No se describe cifrado o una exigencia de rescate.","Los anuncios no explican esa saturación de infraestructura.");
            Add("ddos-2","DDoS","ddos-detect","La caída es una señal, no un diagnóstico","Lentitud y caída pueden tener muchas causas. Para investigar DDoS se revisan volumen, orígenes, recursos y tráfico respecto al comportamiento habitual.","Un sitio va lento durante una promoción. ¿Qué concluyes primero?","Hay que analizar tráfico y recursos antes de atribuirlo a DDoS.","Toda lentitud confirma automáticamente una botnet.","Si hay visitantes reales no puede existir un ataque simultáneo.","La disponibilidad degradada es compatible con DDoS, pero no lo demuestra por sí sola.","También pueden existir fallos o sobrecarga legítima.","Tráfico legítimo y malicioso pueden coexistir.");
            Add("ddos-3","DDoS","ddos-mitigate","Mitigar antes del cuello de botella","Coordina con ISP/CDN o servicio anti-DDoS para filtrar tráfico antes de saturar el enlace. WAF y límites de tasa ayudan según el tipo de ataque, pero no bastan para todos.","Un ataque supera la capacidad del enlace de un portal. ¿Qué respuesta es adecuada?","Activar mitigación upstream con el proveedor o servicio anti-DDoS.","Confiar únicamente en reglas del firewall detrás del enlace saturado.","Restaurar una copia de los archivos web como única medida.","El filtrado debe actuar antes del recurso saturado y ajustarse al tipo de ataque.","El enlace puede colapsar antes de que el firewall local filtre.","Un backup no detiene tráfico que agota recursos.");
            Add("ddos-4","DDoS","ddos-compare","Respuestas diferentes","DDoS: mantener disponibilidad y filtrar tráfico coordinadamente. Ransomware: aislar el compromiso, investigar, sanear y recuperar. No existe una única defensa para todos los incidentes.","¿Qué comparación de respuestas tiene sentido?","DDoS: mitigar tráfico; ransomware: contener el compromiso y recuperar sistemas/datos.","En ambos basta con cambiar la contraseña del administrador.","En ambos basta con reiniciar todos los equipos.","Las medidas se eligen por el comportamiento y el recurso afectado, siguiendo un procedimiento de respuesta.","Cambiar una clave por sí solo no resuelve saturación ni cifrado.","Reiniciar no aborda la causa y puede perder evidencias.");
        }
    }
}
